  p_DriverClass_3e3235c9 := 'RealtimeAgentType';
  p_UIFormSectionExpandedByDefault_3e3235c9 := FALSE;
  p_ConfigSchema_3e3235c9 := '{"$schema":"http://json-schema.org/draft-07/schema#","title":"Realtime Co-Agent TypeConfiguration","description":"Configuration payload for agents of the Realtime type — the agent''s realtime profile. Effective config = AIAgentType.DefaultConfiguration <- AIAgent.TypeConfiguration <- runtime overrides (later layers win per key, deep-merged).","type":"object","additionalProperties":false,"properties":{"realtime":{"type":"object","additionalProperties":false,"properties":{"modelPreference":{"type":"string","description":"Preferred realtime AI model (name or ID). Used unless an authorized runtime override supplies a different model."},"voice":{"type":"object","additionalProperties":false,"properties":{"default":{"type":"object","additionalProperties":false,"properties":{"tone":{"type":"string","description":"Spoken tone folded into the session system prompt (e.g. ''warm, unhurried'')."},"speakingStyle":{"type":"string","description":"Speaking style folded into the session system prompt (e.g. ''concise, plain language'')."},"voice":{"type":"string","description":"Provider-AGNOSTIC voice id, used whichever vendor ends up running the session (every realtime driver reads the neutral ''voice'' key). Set this to author a voice without knowing the vendor. Wins over a ''providers.<key>.voice'' entry; the matching provider bag still contributes its other settings."},"firstMessage":{"type":"string","description":"The opening utterance the agent SPEAKS FIRST, verbatim, before the user says anything — authored here rather than in the prompt because a provider that waits for user audio produces nothing at all until it hears some, whatever the prompt says. Omit it and the agent waits for the user, as before. Wins over a ''providers.<key>.firstMessage'' entry. Honored by drivers with a provider-native opening utterance — ElevenLabs maps it to the agent.first_message override, AssemblyAI to its greeting session slot. Drivers without one ignore it and open